const body = $input.first().json.body || $input.first().json;
const ip = body.ip || $input.first().json.headers?.['x-forwarded-for']?.split(',')[0].trim();
if (!ip) throw new Error('ip is required');
return [{ json: { ip } }];

const geo = $input.first().json;
const countryCode = geo.country_code || 'UNKNOWN';
const langMap = {
  FR:'french',DE:'german',GB:'english',ES:'spanish',IT:'italian',
  MA:'arabic',DZ:'arabic',TN:'arabic',SA:'arabic',EG:'arabic',
  SN:'french',CM:'french',BE:'dutch',NL:'dutch',PT:'portuguese',
  BR:'portuguese',TR:'turkish',PL:'polish',US:'english',CA:'english'
};
const language = langMap[countryCode] || 'english';
const rtlLangs = ['arabic','hebrew','persian','dari','urdu'];
return [{ json: {
  ip: $('Extract IP').item.json.ip,
  countryCode,
  countryName: geo.country_name || 'Unknown',
  city: geo.city || null,
  language,
  rtl: rtlLangs.includes(language),
  timezone: geo.timezone || null,
  latitude: geo.latitude || null,
  longitude: geo.longitude || null
} }];

const geo = $('Enrich Geo Data').item.json;
const countries = $input.first().json.countries || [];
const match = countries.find(c => c.code === geo.countryCode);
return [{ json: { ...geo, hasActivePipeline: match ? match.pipeline?.status === 'active' : false, pipelineStatus: match?.pipeline?.status || null } }];
